[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Fresh Pantry — Discover Everyday Deliciousness</title>
  <meta name="description" content="A neighborhood grocery store offering unique, high-quality food products at great prices.">
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Nunito:wght@400;600;700;800&family=DM+Sans:wght@400;500;600&display=swap" rel="stylesheet">
  <script src="https://unpkg.com/lucide@latest/dist/umd/lucide.min.js"></script>
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --green-900: #1B4332;
      --green-700: #2D6A4F;
      --green-600: #40916C;
      --green-500: #52B788;
      --green-400: #74C69D;
      --green-100: #D8F3DC;
      --cream: #FEFAE0;
      --cream-dark: #F5F0D0;
      --orange: #F4A261;
      --orange-dark: #E76F51;
      --terracotta: #D4603A;
      --white: #FFFFFF;
      --gray-50: #F9FAFB;
      --gray-100: #F3F4F6;
      --gray-200: #E5E7EB;
      --gray-400: #9CA3AF;
      --gray-600: #4B5563;
      --gray-700: #374151;
      --gray-800: #1F2937;
      --gray-900: #111827;
      --font-heading: 'Nunito', sans-serif;
      --font-body: 'DM Sans', sans-serif;
      --radius: 1rem;
      --radius-sm: 0.625rem;
      --radius-lg: 1.5rem;
      --shadow-sm: 0 1px 3px rgba(0,0,0,0.06), 0 1px 2px rgba(0,0,0,0.04);
      --shadow-md: 0 4px 14px rgba(0,0,0,0.08);
      --shadow-lg: 0 10px 30px rgba(0,0,0,0.1);
      --transition: 200ms ease;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: var(--font-body);
      color: var(--gray-800);
      background: var(--cream);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }

    h1, h2, h3, h4, h5, h6 { font-family: var(--font-heading); font-weight: 800; line-height: 1.2; }

    a { color: inherit; text-decoration: none; }
    img { max-width: 100%; display: block; }
    button { font-family: var(--font-body); cursor: pointer; border: none; }
    input { font-family: var(--font-body); }

    .container { max-width: 1200px; margin: 0 auto; padding: 0 1.5rem; }

    /* ─── HEADER ─── */
    .header {
      position: sticky; top: 0; z-index: 100;
      background: rgba(254, 250, 224, 0.92);
      backdrop-filter: blur(12px);
      border-bottom: 1px solid rgba(45, 106, 79, 0.08);
      transition: box-shadow var(--transition);
    }
    .header.scrolled { box-shadow: var(--shadow-md); }
    .header-inner {
      display: flex; align-items: center; justify-content: space-between;
      padding: 1rem 1.5rem; max-width: 1200px; margin: 0 auto;
    }
    .logo { display: flex; align-items: center; gap: 0.625rem; }
    .logo-icon {
      width: 40px; height: 40px; background: var(--green-700);
      border-radius: var(--radius-sm); display: flex; align-items: center; justify-content: center;
      color: var(--white); font-size: 1.25rem;
    }
    .logo-text { font-family: var(--font-heading); font-weight: 800; font-size: 1.35rem; color: var(--green-900); }
    .logo-text span { color: var(--orange); }

    .nav-links { display: flex; gap: 2rem; list-style: none; }
    .nav-links a {
      font-weight: 600; font-size: 0.95rem; color: var(--gray-700);
      transition: color var(--transition); position: relative; padding: 0.25rem 0;
    }
    .nav-links a::after {
      content: ''; position: absolute; bottom: -2px; left: 0; width: 0;
      height: 2px; background: var(--green-600); border-radius: 1px;
      transition: width var(--transition);
    }
    .nav-links a:hover { color: var(--green-700); }
    .nav-links a:hover::after { width: 100%; }

    .nav-cta {
      background: var(--green-700); color: var(--white); padding: 0.625rem 1.5rem;
      border-radius: 50px; font-weight: 700; font-size: 0.9rem;
      transition: all var(--transition); display: flex; align-items: center; gap: 0.5rem;
    }
    .nav-cta:hover { background: var(--green-600); transform: translateY(-1px); box-shadow: var(--shadow-md); }

    .mobile-toggle { display: none; background: none; padding: 0.5rem; color: var(--green-900); }

    /* ─── HERO ─── */
    .hero {
      padding: 6rem 1.5rem 5rem;
      background: linear-gradient(160deg, var(--cream) 0%, #E8F5E1 50%, var(--cream-dark) 100%);
      position: relative; overflow: hidden; text-align: center;
    }
    .hero::before {
      content: ''; position: absolute; top: -50%; right: -20%;
      width: 600px; height: 600px;
      background: radial-gradient(circle, rgba(116, 198, 157, 0.15) 0%, transparent 70%);
      border-radius: 50%;
    }
    .hero::after {
      content: ''; position: absolute; bottom: -30%; left: -10%;
      width: 400px; height: 400px;
      background: radial-gradient(circle, rgba(244, 162, 97, 0.12) 0%, transparent 70%);
      border-radius: 50%;
    }
    .hero-content { position: relative; z-index: 1; max-width: 750px; margin: 0 auto; }
    .hero-badge {
      display: inline-flex; align-items: center; gap: 0.5rem;
      background: rgba(45, 106, 79, 0.08); color: var(--green-700);
      padding: 0.5rem 1.25rem; border-radius: 50px;
      font-weight: 700; font-size: 0.85rem; margin-bottom: 1.75rem;
      border: 1px solid rgba(45, 106, 79, 0.12);
    }
    .hero h1 {
      font-size: clamp(2.5rem, 5.5vw, 4rem); color: var(--green-900);
      margin-bottom: 1.25rem; letter-spacing: -0.02em;
    }
    .hero h1 .accent { color: var(--orange); }
    .hero p {
      font-size: clamp(1.05rem, 2vw, 1.25rem); color: var(--gray-600);
      max-width: 600px; margin: 0 auto 2.5rem; line-height: 1.7;
    }
    .hero-actions { display: flex; gap: 1rem; justify-content: center; flex-wrap: wrap; }
    .btn {
      padding: 0.875rem 2rem; border-radius: 50px; font-weight: 700;
      font-size: 1rem; transition: all var(--transition);
      display: inline-flex; align-items: center; gap: 0.5rem;
    }
    .btn-primary {
      background: var(--green-700); color: var(--white);
      box-shadow: 0 4px 14px rgba(45, 106, 79, 0.3);
    }
    .btn-primary:hover { background: var(--green-600); transform: translateY(-2px); box-shadow: 0 6px 20px rgba(45, 106, 79, 0.35); }
    .btn-secondary {
      background: var(--white); color: var(--green-700);
      border: 2px solid var(--green-700);
    }
    .btn-secondary:hover { background: var(--green-100); transform: translateY(-2px); }

    /* ─── SECTION TITLES ─── */
    .section-header { text-align: center; margin-bottom: 3rem; }
    .section-header h2 { font-size: clamp(1.75rem, 3.5vw, 2.5rem); color: var(--green-900); margin-bottom: 0.75rem; }
    .section-header p { font-size: 1.1rem; color: var(--gray-600); max-width: 550px; margin: 0 auto; }

    /* ─── FEATURED PRODUCTS ─── */
    .featured-products { padding: 5rem 0; background: var(--white); }
    .carousel-wrapper { position: relative; }
    .carousel-track-container {
      overflow: hidden; border-radius: var(--radius-lg);
      margin: 0 3.5rem;
    }
    .carousel-track {
      display: flex; gap: 1.5rem;
      transition: transform 450ms cubic-bezier(0.25, 0.46, 0.45, 0.94);
    }
    .product-card {
      flex: 0 0 calc(25% - 1.125rem); min-width: 240px;
      background: var(--cream); border-radius: var(--radius);
      overflow: hidden; transition: all var(--transition);
      border: 1px solid rgba(45, 106, 79, 0.06);
    }
    .product-card:hover { transform: translateY(-6px); box-shadow: var(--shadow-lg); }
    .product-img {
      width: 100%; height: 200px; object-fit: cover;
      background: linear-gradient(135deg, var(--green-100), var(--cream-dark));
    }
    .product-img-placeholder {
      width: 100%; height: 200px;
      display: flex; align-items: center; justify-content: center;
      font-size: 3.5rem;
      background: linear-gradient(135deg, var(--green-100) 0%, var(--cream-dark) 100%);
    }
    .product-info { padding: 1.25rem; }
    .product-name { font-family: var(--font-heading); font-weight: 700; font-size: 1rem; color: var(--green-900); margin-bottom: 0.375rem; }
    .product-desc { font-size: 0.85rem; color: var(--gray-600); margin-bottom: 0.75rem; line-height: 1.5; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
    .product-footer { display: flex; align-items: center; justify-content: space-between; }
    .product-price { font-family: var(--font-heading); font-weight: 800; font-size: 1.2rem; color: var(--orange-dark); }
    .product-add {
      width: 36px; height: 36px; border-radius: 50%;
      background: var(--green-700); color: var(--white);
      display: flex; align-items: center; justify-content: center;
      transition: all var(--transition); font-size: 1.1rem;
    }
    .product-add:hover { background: var(--green-600); transform: scale(1.1); }

    .carousel-btn {
      position: absolute; top: 50%; transform: translateY(-50%);
      width: 48px; height: 48px; border-radius: 50%;
      background: var(--white); color: var(--green-700);
      box-shadow: var(--shadow-md); display: flex; align-items: center; justify-content: center;
      transition: all var(--transition); z-index: 2; border: 2px solid var(--green-100);
    }
    .carousel-btn:hover { background: var(--green-700); color: var(--white); box-shadow: var(--shadow-lg); }
    .carousel-btn:disabled { opacity: 0.3; cursor: not-allowed; }
    .carousel-btn:disabled:hover { background: var(--white); color: var(--green-700); }
    .carousel-btn-left { left: 0; }
    .carousel-btn-right { right: 0; }

    /* ─── SEASONAL PICKS ─── */
    .seasonal-picks { padding: 5rem 0; }
    .seasonal-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 1.5rem; }
    .seasonal-card {
      background: var(--white); border-radius: var(--radius); padding: 1.75rem;
      border: 1px solid rgba(45, 106, 79, 0.06);
      transition: all var(--transition); position: relative; overflow: hidden;
    }
    .seasonal-card::before {
      content: ''; position: absolute; top: 0; left: 0; right: 0;
      height: 4px; background: linear-gradient(90deg, var(--green-500), var(--orange));
      border-radius: var(--radius) var(--radius) 0 0;
    }
    .seasonal-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }
    .seasonal-emoji { font-size: 2.5rem; margin-bottom: 1rem; }
    .seasonal-name { font-family: var(--font-heading); font-weight: 700; font-size: 1.05rem; color: var(--green-900); margin-bottom: 0.5rem; }
    .seasonal-desc { font-size: 0.9rem; color: var(--gray-600); margin-bottom: 1rem; line-height: 1.5; }
    .seasonal-price { font-family: var(--font-heading); font-weight: 800; font-size: 1.15rem; color: var(--orange-dark); }
    .seasonal-badge {
      position: absolute; top: 1rem; right: 1rem;
      background: var(--orange); color: var(--white);
      padding: 0.25rem 0.75rem; border-radius: 50px;
      font-size: 0.75rem; font-weight: 700;
    }

    /* ─── BRAND HIGHLIGHTS ─── */
    .brand-highlights {
      background: linear-gradient(135deg, var(--green-900) 0%, var(--green-700) 100%);
      padding: 4.5rem 1.5rem; color: var(--white); position: relative; overflow: hidden;
    }
    .brand-highlights::before {
      content: ''; position: absolute; top: -60%; right: -10%;
      width: 500px; height: 500px;
      background: radial-gradient(circle, rgba(244, 162, 97, 0.15) 0%, transparent 70%);
      border-radius: 50%;
    }
    .brand-highlights::after {
      content: ''; position: absolute; bottom: -40%; left: -5%;
      width: 400px; height: 400px;
      background: radial-gradient(circle, rgba(82, 183, 136, 0.15) 0%, transparent 70%);
      border-radius: 50%;
    }
    .highlights-grid {
      display: grid; grid-template-columns: repeat(4, 1fr); gap: 2rem;
      max-width: 1200px; margin: 0 auto; position: relative; z-index: 1;
    }
    .highlight-item { text-align: center; }
    .highlight-number {
      font-family: var(--font-heading); font-weight: 800;
      font-size: clamp(2.5rem, 4vw, 3.5rem); color: var(--orange);
      line-height: 1.1; margin-bottom: 0.5rem;
    }
    .highlight-label { font-weight: 600; font-size: 1.05rem; margin-bottom: 0.375rem; color: var(--white); }
    .highlight-desc { font-size: 0.875rem; color: rgba(255,255,255,0.7); line-height: 1.5; }

    /* ─── CATEGORIES ─── */
    .categories { padding: 5rem 0; background: var(--white); }
    .categories-grid {
      display: grid; grid-template-columns: repeat(5, 1fr); gap: 1.25rem;
    }
    .category-card {
      position: relative; border-radius: var(--radius); overflow: hidden;
      aspect-ratio: 3/4; cursor: pointer;
    }
    .category-bg {
      width: 100%; height: 100%; object-fit: cover;
      transition: transform 400ms ease;
    }
    .category-bg-placeholder {
      width: 100%; height: 100%; display: flex;
      align-items: center; justify-content: center;
      font-size: 4rem; transition: transform 400ms ease;
    }
    .category-card:nth-child(1) .category-bg-placeholder { background: linear-gradient(135deg, #FFE4C4, #FFF0DB); }
    .category-card:nth-child(2) .category-bg-placeholder { background: linear-gradient(135deg, #C8E6C9, #E8F5E9); }
    .category-card:nth-child(3) .category-bg-placeholder { background: linear-gradient(135deg, #BBDEFB, #E3F2FD); }
    .category-card:nth-child(4) .category-bg-placeholder { background: linear-gradient(135deg, #FFE0B2, #FFF3E0); }
    .category-card:nth-child(5) .category-bg-placeholder { background: linear-gradient(135deg, #FFF9C4, #FFFDE7); }

    .category-overlay {
      position: absolute; inset: 0;
      background: linear-gradient(to top, rgba(27, 67, 50, 0.85) 0%, rgba(27, 67, 50, 0.2) 50%, transparent 100%);
      display: flex; flex-direction: column; justify-content: flex-end;
      padding: 1.5rem; transition: all 300ms ease;
    }
    .category-card:hover .category-bg-placeholder,
    .category-card:hover .category-bg { transform: scale(1.08); }
    .category-card:hover .category-overlay {
      background: linear-gradient(to top, rgba(27, 67, 50, 0.92) 0%, rgba(27, 67, 50, 0.4) 60%, rgba(27, 67, 50, 0.1) 100%);
    }

    .category-name {
      font-family: var(--font-heading); font-weight: 800; font-size: 1.15rem;
      color: var(--white); margin-bottom: 0.25rem;
    }
    .category-desc {
      font-size: 0.8rem; color: rgba(255,255,255,0.8); line-height: 1.4;
      opacity: 0; transform: translateY(8px);
      transition: all 300ms ease;
    }
    .category-card:hover .category-desc { opacity: 1; transform: translateY(0); }

    /* ─── STORE LOCATOR ─── */
    .store-locator { padding: 5rem 0; }
    .locator-box {
      max-width: 700px; margin: 0 auto;
      background: var(--white); border-radius: var(--radius-lg); padding: 3rem;
      box-shadow: var(--shadow-md); border: 1px solid rgba(45, 106, 79, 0.06);
    }
    .search-row { display: flex; gap: 0.75rem; margin-bottom: 0.5rem; }
    .search-input {
      flex: 1; padding: 0.875rem 1.25rem; border-radius: 50px;
      border: 2px solid var(--gray-200); font-size: 1rem;
      transition: border-color var(--transition); background: var(--gray-50);
      outline: none;
    }
    .search-input:focus { border-color: var(--green-500); background: var(--white); }
    .search-input::placeholder { color: var(--gray-400); }
    .search-btn {
      background: var(--green-700); color: var(--white); padding: 0.875rem 2rem;
      border-radius: 50px; font-weight: 700; font-size: 1rem;
      transition: all var(--transition); display: flex; align-items: center; gap: 0.5rem;
      white-space: nowrap;
    }
    .search-btn:hover { background: var(--green-600); transform: translateY(-1px); }

    .store-results { display: none; margin-top: 2rem; }
    .store-results.visible { display: block; }
    .store-results-header { font-family: var(--font-heading); font-weight: 700; font-size: 1.1rem; color: var(--green-900); margin-bottom: 1rem; }

    .store-card {
      display: flex; align-items: center; gap: 1.25rem;
      padding: 1.25rem; border-radius: var(--radius-sm);
      border: 1px solid var(--gray-200); margin-bottom: 0.75rem;
      transition: all var(--transition); background: var(--gray-50);
    }
    .store-card:hover { border-color: var(--green-400); background: var(--white); box-shadow: var(--shadow-sm); }
    .store-icon {
      width: 48px; height: 48px; border-radius: var(--radius-sm);
      background: var(--green-100); color: var(--green-700);
      display: flex; align-items: center; justify-content: center; flex-shrink: 0;
    }
    .store-details { flex: 1; }
    .store-name { font-family: var(--font-heading); font-weight: 700; color: var(--green-900); margin-bottom: 0.125rem; }
    .store-address { font-size: 0.9rem; color: var(--gray-600); }
    .store-hours { font-size: 0.85rem; color: var(--gray-400); }
    .store-distance {
      font-family: var(--font-heading); font-weight: 800;
      color: var(--orange-dark); font-size: 1rem; white-space: nowrap;
    }

    /* ─── NEWSLETTER ─── */
    .newsletter {
      padding: 5rem 0; background: var(--white);
    }
    .newsletter-box {
      max-width: 600px; margin: 0 auto; text-align: center;
      background: linear-gradient(135deg, var(--green-100) 0%, var(--cream) 100%);
      border-radius: var(--radius-lg); padding: 3.5rem 2.5rem;
      border: 1px solid rgba(45, 106, 79, 0.08);
    }
    .newsletter-box h2 { font-size: 2rem; color: var(--green-900); margin-bottom: 0.75rem; }
    .newsletter-box p { color: var(--gray-600); margin-bottom: 2rem; font-size: 1.05rem; }
    .newsletter-form { display: flex; gap: 0.75rem; max-width: 440px; margin: 0 auto; }
    .newsletter-input {
      flex: 1; padding: 0.875rem 1.25rem; border-radius: 50px;
      border: 2px solid var(--gray-200); font-size: 1rem;
      outline: none; background: var(--white); transition: border-color var(--transition);
    }
    .newsletter-input:focus { border-color: var(--green-500); }
    .newsletter-input::placeholder { color: var(--gray-400); }
    .newsletter-btn {
      background: var(--orange); color: var(--white); padding: 0.875rem 1.75rem;
      border-radius: 50px; font-weight: 700; font-size: 1rem;
      transition: all var(--transition); white-space: nowrap;
    }
    .newsletter-btn:hover { background: var(--orange-dark); transform: translateY(-1px); }
    .newsletter-confirm {
      display: none; margin-top: 1.25rem;
      color: var(--green-700); font-weight: 600; font-size: 0.95rem;
    }
    .newsletter-confirm.visible { display: flex; align-items: center; justify-content: center; gap: 0.5rem; }

    /* ─── FOOTER ─── */
    .footer {
      background: var(--green-900); color: rgba(255,255,255,0.8); padding: 4rem 1.5rem 2rem;
    }
    .footer-grid {
      display: grid; grid-template-columns: 1.5fr repeat(4, 1fr); gap: 2.5rem;
      max-width: 1200px; margin: 0 auto; padding-bottom: 2.5rem;
      border-bottom: 1px solid rgba(255,255,255,0.1);
    }
    .footer-brand p { margin-top: 1rem; font-size: 0.9rem; line-height: 1.6; color: rgba(255,255,255,0.6); }
    .footer-col h4 {
      font-family: var(--font-heading); font-weight: 700;
      color: var(--white); margin-bottom: 1rem; font-size: 0.95rem;
    }
    .footer-col ul { list-style: none; }
    .footer-col li { margin-bottom: 0.625rem; }
    .footer-col a {
      font-size: 0.9rem; color: rgba(255,255,255,0.6);
      transition: color var(--transition);
    }
    .footer-col a:hover { color: var(--orange); }
    .footer-bottom {
      max-width: 1200px; margin: 1.5rem auto 0;
      display: flex; align-items: center; justify-content: space-between;
      font-size: 0.85rem; color: rgba(255,255,255,0.4);
    }
    .footer-socials { display: flex; gap: 1rem; }
    .footer-socials a {
      width: 36px; height: 36px; border-radius: 50%;
      background: rgba(255,255,255,0.08); color: rgba(255,255,255,0.6);
      display: flex; align-items: center; justify-content: center;
      transition: all var(--transition);
    }
    .footer-socials a:hover { background: var(--orange); color: var(--white); }

    /* ─── SCROLL ANIMATIONS ─── */
    .fade-in {
      opacity: 0; transform: translateY(24px);
      transition: opacity 600ms ease, transform 600ms ease;
    }
    .fade-in.visible { opacity: 1; transform: translateY(0); }

    /* ─── RESPONSIVE ─── */
    @media (max-width: 1024px) {
      .categories-grid { grid-template-columns: repeat(3, 1fr); }
      .carousel-track-container { margin: 0 3rem; }
      .product-card { flex: 0 0 calc(33.333% - 1rem); }
    }

    @media (max-width: 768px) {
      .nav-links { display: none; }
      .nav-cta { display: none; }
      .mobile-toggle { display: flex; }

      .mobile-nav {
        display: none; position: absolute; top: 100%; left: 0; right: 0;
        background: var(--cream); border-bottom: 1px solid var(--gray-200);
        padding: 1rem 1.5rem; box-shadow: var(--shadow-md);
      }
      .mobile-nav.open { display: block; }
      .mobile-nav ul { list-style: none; }
      .mobile-nav li { padding: 0.75rem 0; border-bottom: 1px solid var(--gray-100); }
      .mobile-nav a { font-weight: 600; font-size: 1rem; color: var(--gray-700); }

      .hero { padding: 4rem 1.5rem 3.5rem; }
      .highlights-grid { grid-template-columns: repeat(2, 1fr); gap: 1.5rem; }
      .categories-grid { grid-template-columns: repeat(2, 1fr); }
      .category-card { aspect-ratio: 1; }
      .carousel-track-container { margin: 0 2.5rem; }
