  <script>
    lucide.createIcons();

    // ─── Sticky header shadow ───
    window.addEventListener('scroll', function() {
      document.getElementById('header').classList.toggle('scrolled', window.scrollY > 10);
    });

    // ─── Mobile nav ───
    function toggleMobileNav() {
      document.getElementById('mobileNav').classList.toggle('open');
    }
    function closeMobileNav() {
      document.getElementById('mobileNav').classList.remove('open');
    }

    // ─── Carousel ───
    (function() {
      var track = document.getElementById('carouselTrack');
      var prevBtn = document.getElementById('carouselPrev');
      var nextBtn = document.getElementById('carouselNext');
      var position = 0;

      function getCardWidth() {
        var card = track.querySelector('.product-card');
        if (!card) return 260;
        var style = window.getComputedStyle(track);
        var gap = parseFloat(style.gap) || 24;
        return card.offsetWidth + gap;
      }

      function getVisibleCards() {
        var container = track.parentElement;
        var cardW = getCardWidth();
        return Math.floor(container.offsetWidth / cardW) || 1;
      }

      function getMaxPosition() {
        var totalCards = track.querySelectorAll('.product-card').length;
        var visible = getVisibleCards();
        return Math.max(0, totalCards - visible);
      }

      function updateCarousel() {
        var cardW = getCardWidth();
        track.style.transform = 'translateX(' + (-position * cardW) + 'px)';
        prevBtn.disabled = position <= 0;
        nextBtn.disabled = position >= getMaxPosition();
      }

      prevBtn.addEventListener('click', function() {
        position = Math.max(0, position - 1);
        updateCarousel();
      });

      nextBtn.addEventListener('click', function() {
        position = Math.min(getMaxPosition(), position + 1);
        updateCarousel();
      });

      window.addEventListener('resize', function() {
        position = Math.min(position, getMaxPosition());
        updateCarousel();
      });

      updateCarousel();
    })();

    // ─── Store locator ───
    function searchStores() {
      var zip = document.getElementById('zipInput').value.trim();
      if (zip.length > 0) {
        document.getElementById('storeResults').classList.add('visible');
        document.getElementById('storeResults').scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      }
    }
    document.getElementById('zipInput').addEventListener('keydown', function(e) {
      if (e.key === 'Enter') searchStores();
    });

    // ─── Newsletter ───
    function subscribeNewsletter(e) {
      e.preventDefault();
      var email = document.getElementById('emailInput').value.trim();
      if (email) {
        document.getElementById('newsletterConfirm').classList.add('visible');
        document.getElementById('emailInput').value = '';
      }
    }

    // ─── Scroll-reveal ───
    (function() {
      var els = document.querySelectorAll('.fade-in');
      var observer = new IntersectionObserver(function(entries) {
        entries.forEach(function(entry) {
          if (entry.isIntersecting) {
            entry.target.classList.add('visible');
            observer.unobserve(entry.target);
          }
        });
      }, { threshold: 0.15, rootMargin: '0px 0px -40px 0px' });
      els.forEach(function(el) { observer.observe(el); });
    })();
  </script>
